INSERT INTO ANALYSE (ID_DOCUMENT, NUM_ANALYSE, PM, AM1, AM2, AM3, AM4, AM5, AM6, AM7, AM8, AM9, AM10, AM11, AM12, SOMMAIRE, TITRE_REFERENCE) VALUES (${SOURCEID}, 1, 'IMPOTS ET TAXES*', 'Enregistrement', 'Taxe sur la valeur vénale des immeubles possédés en France par des personnes morales', 'Personnes imposables', 'Exonération', 'Justificatifs ', 'Communication de l''information délivrée à l''administration fiscale', 'Modalités ', 'Caractère exclusif (oui)', NULL, NULL, NULL, NULL, 'Selon l''article 990 E du code général des impôts, les entités juridiques qui entrent dans le champ d''application de la taxe de 3% prévue à l''article 990 D du code général des impôts peuvent bénéficier d''une exonération totale sur le fondement du d du 3° de cet article, si elles communiquent chaque année à l''administration fiscale certains renseignements ou si elles prennent et respectent l''engagement de communiquer à l''administration fiscale, sur sa demande, un certain nombre de renseignements.\n\nIl en résulte que si ces entités ont le choix, pour s''exonérer du paiement de la taxe prévue à l''article 990 E, entre deux modalités de communication de l''information à l''administration fiscale, celles-ci sont exclusives l''une de l''autre', NULL);